package com.kexu;
import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.context.HttpSessionSecurityContextRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.client.RestClient;import java.util.*;import java.net.URI;import java.net.http.HttpClient;import java.time.Duration;import org.springframework.http.client.JdkClientHttpRequestFactory;
@RestController @RequestMapping("/api") public class Api {
 private final Accounts accounts; private final Courses courses; private final PasswordEncoder encoder; private final String aiUrl,aiKey,aiModel,aiAllowedHosts;
 Api(Accounts a,Courses c,PasswordEncoder e,@Value("${app.ai-url}") String u,@Value("${app.ai-key}") String k,@Value("${app.ai-model}") String m,@Value("${app.ai-allowed-hosts}") String hosts){accounts=a;courses=c;encoder=e;aiUrl=u;aiKey=k;aiModel=m;aiAllowedHosts=hosts;}
 record Credentials(String username,String password){} record Prompt(String message,String url,String key,String model,String systemPrompt,Double temperature){}
 private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);} private Account current(){String name=SecurityContextHolder.getContext().getAuthentication().getName();return accounts.findByUsername(name).orElseThrow();} private Map<String,Object> profile(Account a){return Map.of("id",a.id,"username",a.username,"role",a.role);}
 @PostMapping("/auth/register") Map<String,Object> register(@RequestBody Credentials c){if(c.username()==null||!c.username().matches("[\\p{IsHan}a-zA-Z0-9_]{1,50}")||c.password()==null||c.password().length()<8||c.password().length()>72)throw bad("用户名需为 1–50 个字符，可使用中文、英文字母、数字或下划线，密码需为 8–72 位");if(accounts.findByUsername(c.username()).isPresent())throw bad("用户名已存在");Account a=new Account();a.username=c.username();a.password=encoder.encode(c.password());a.role="USER";return profile(accounts.save(a));}
 @PostMapping("/auth/login") Map<String,Object> login(@RequestBody Credentials c,HttpServletRequest request){Account a=c.username()==null?null:accounts.findByUsername(c.username()).orElse(null);if(a==null||c.password()==null||!encoder.matches(c.password(),a.password))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"用户名或密码错误");request.getSession().invalidate();var auth=new UsernamePasswordAuthenticationToken(a.username,null,List.of(new SimpleGrantedAuthority("ROLE_"+a.role)));var ctx=SecurityContextHolder.createEmptyContext();ctx.setAuthentication(auth);SecurityContextHolder.setContext(ctx);request.getSession(true).setAttribute(HttpSessionSecurityContextRepository.SPRING_SECURITY_CONTEXT_KEY,ctx);return profile(a);}
 @PostMapping("/auth/logout") void logout(HttpServletRequest request){request.getSession().invalidate();SecurityContextHolder.clearContext();} @GetMapping("/auth/me") Map<String,Object> me(){return profile(current());}
 @GetMapping("/courses") List<Course> list(){return courses.findByOwnerId(current().id);} private void check(Course c){if(c.endPeriod<c.startPeriod||c.endWeek<c.startWeek)throw bad("结束节次和周次不能早于开始值");}
 @PostMapping("/courses") Course create(@Valid @RequestBody Course c){check(c);c.id=null;c.ownerId=current().id;return courses.save(c);} @PutMapping("/courses/{id}") Course update(@PathVariable Long id,@Valid @RequestBody Course c){Course old=courses.findByIdAndOwnerId(id,current().id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));check(c);c.id=old.id;c.ownerId=old.ownerId;return courses.save(c);} @DeleteMapping("/courses/{id}") void delete(@PathVariable Long id){courses.delete(courses.findByIdAndOwnerId(id,current().id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}
 @GetMapping("/admin/users") List<Map<String,Object>> users(){return accounts.findAll().stream().map(this::profile).toList();}
 private String value(String s){return s==null?"":s.trim();}
 @PostMapping("/ai/chat") Object chat(@RequestBody Prompt p){
  if(p.message()==null||p.message().isBlank()||p.message().length()>4000)throw bad("请输入不超过 4000 字的问题");
  String url=value(p.url()),key=value(p.key()),model=value(p.model());
  if(url.isEmpty()&&key.isEmpty()&&model.isEmpty()){url=aiUrl;key=aiKey;model=aiModel;}
  if(url.isBlank()||key.isBlank()||model.isBlank())throw bad("请在模型设置中完整填写 API 地址、密钥和模型名称，或配置服务器默认模型");
  if(url.length()>2048||key.length()>2048||model.length()>100||key.contains("\r")||key.contains("\n"))throw bad("模型设置格式无效");
  URI uri;try{uri=URI.create(url);}catch(IllegalArgumentException e){throw bad("API 地址格式无效");}
  Set<String> hosts=new HashSet<>();for(String host:aiAllowedHosts.split(","))hosts.add(host.trim().toLowerCase(Locale.ROOT));
  if(!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||(uri.getPort()!=-1&&uri.getPort()!=443)||uri.getFragment()!=null||uri.getQuery()!=null||!hosts.contains(uri.getHost().toLowerCase(Locale.ROOT)))throw bad("API 地址必须使用 HTTPS，且域名需要在服务器允许列表中");
  String prompt=value(p.systemPrompt());if(prompt.isBlank())prompt="你是大学课程学习助手，请用中文准确简洁地回答。";if(prompt.length()>2000)throw bad("助手角色不能超过 2000 字");
  double temperature=p.temperature()==null?0.7:p.temperature();if(!Double.isFinite(temperature)||temperature<0||temperature>2)throw bad("回答随机性须在 0 到 2 之间");
  return new ModelClient().chat(uri,key,model,prompt,p.message(),temperature);
 }
}
